import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or until closed,
    up to 4096 bytes."""
    if server_hostname is None:
        server_hostname = host
    # Create a TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap with TLS client socket that verifies cert and hostname
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        # Read bytes until newline or EOF or 4096 bytes max
        greeting = bytearray()
        while len(greeting) < 4096:
            chunk = tls_sock.recv(4096 - len(greeting))
            if not chunk:
                # Connection closed
                break
            greeting.extend(chunk)
            if b"\n" in chunk:
                # Found newline, stop reading
                break
        # Return bytes up to and including first newline if any
        idx = greeting.find(b"\n")
        if idx >= 0:
            return bytes(greeting[:idx + 1])
        else:
            return bytes(greeting)
    finally:
        sock.close()

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert and hostname, and return greeting bytes.

    The greeting is the bytes received up to and including the first newline byte,
    or until the connection closes, up to 4096 bytes.

    Verification failures raise ssl.SSLError or ssl.CertificateError.
    """
    if server_hostname is None:
        server_hostname = host
    with socket.create_connection((host, port)) as sock:
        with wrap_client_socket(sock, server_hostname, cafile) as tls_sock:
            # Read up to 4096 bytes or until newline inclusive
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop after the first newline
                    break
            # Return bytes up to and including the first newline
            newline_index = data.find(b"\n")
            if newline_index >= 0:
                return bytes(data[:newline_index + 1])
            else:
                return bytes(data)
